import task_env
from task_env import OWN
from prepare import read,write,hashfile
from datetime import datetime,timezone

findings={
'Plane468':'Native PNG individually viewed: all 19 original tile faces remain, six white interiors clearly white and thirteen black faces black; no outer tile is drawn. Three orientation colors join a full actual white hex contact template to the 30 actual exposed unit contacts. Colored contact edges do not add faces or turn black faces white. Original black-black invisible seams remain invisible. The physical-tile wording counts face colors, not boundary ink; the new outline has no alternative face-color count. Repeated orientation marks are contact-count units, not an unsupported length symbol.',
'Plane469':'Native PNG individually viewed: five black and eleven white cell interiors and labels A,B,C,D remain. Four row-preserving cell pairs have open, single-edge color matches; one pair has two black cells and three pairs each have one black/one white cell. No dot, closed new cell contour, painted receiver, extra gridline or diagonal is drawn. Colors on grid boundaries are visibly thin and cannot reasonably make any white interior a filled black square. BD stays the named diagonal through B and D. Human diagonal-reflection minimum remains 4.',
'Plane472':'Native PNG individually viewed: all 5x5 lines, four light-gray concave blades, black sloping edges and central meeting point remain. Blue/green unit L at upper-right is paired to the actual unit reflex L of only the upper-left blade. Each mark is a specific horizontal/vertical feature counterpart; no complete blade is recolored, no fill or grid target added. The missing convex/reflex occupancy distinction remains visibly readable. Human area stays 6.',
'Plane475':'Native PNG individually viewed: all eight original black dots remain distinct; six thin auxiliary segments join only six existing dots, with no intersections except their original endpoints. The two original top middle dots remain unmarked and selectable. Green horizontal bases and orange vertical legs are real unit counterparts; red/blue opposite-slope hypotenuses encode orientation, not length. Both drawn examples are congruent (1,1,2); all triples of the eight original points remain the question target. Appearance colors do not redefine numerical congruence. No extra vertices/pips are introduced.',
'Plane479':'Native PNG individually viewed: A-J all remain legible and ten original dots unchanged. AC is one true auxiliary diagonal between original named vertices. The two base/leg/hypotenuse matches frame actual ABC and KIJ. The gray triangular wedge ACK between red AC and original upper black AJ is clearly present (base CK is about75px; it tapers to A); nothing recolors it white. All three pieces retain the exact original light-gray fill. K is only an unmarked pre-existing AJ/HI crossing. Original named pentagon AJICB and its full gray area remain the target; numerical area is4/12=1/3. The paper-ink transformation objection does not apply to this fixed numerical diagram.'}
for q,description in findings.items():
    for d in (OWN/q).iterdir():
        if not d.is_dir() or not (d/'design.json').is_file():continue
        design=read(d/'design.json')
        write(d/'primary_review.json',{'question_id':q,'variant_id':design['variant_id'],'reviewed_at_utc':datetime.now(timezone.utc).isoformat(),'reviewer_role':'PRIMARY DESIGNER ONLY, not independent second review','source_JPG_formal_PNG_and_old_candidate_PNGs_individually_viewed':True,'actual_frozen_candidate_native_PNG_viewed':True,'native_size':[768,768],'visual_findings':description,'math_proof':str(d/'math_proof.json'),'marker_reviews':[{**r,'use':'Specific declared feature/counting/decomposition role','legality':'Allowed schema operation; exact actual source location','human_clarity':'Checked in combined actual PNG; original target identity preserved'} for r in design['marker_roles']],'normalization_noop_replay_and_native_preservation':str(d/'render_check.json'),'unique_original_answer_preserved':True,'proceed_to_API':True,'candidate_sha256':hashfile(d/'candidate.png'),'frozen_design_sha256':hashfile(d/'design.json'),'limits':['Primary judgment only; parent NEW independent review required for any possible candidate.','Two observed finals cannot prove mechanism, causality or statistical improvement.','No original control correctness or identical narrative is imposed.']})
